const mergeSiteContent = (content) => {
  const merged = { ...defaultSiteContent, ...content };
  for (const [key, previousValue] of Object.entries(previousPublicCopy)) {
    if (content[key] === previousValue) merged[key] = defaultSiteContent[key];
  }
  return merged;
};

